package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type ConsoleScanner struct {
	scanner *bufio.Scanner
	tokens  []string
	index   int
}

func NewConsoleScanner() *ConsoleScanner {
	return &ConsoleScanner{
		scanner: bufio.NewScanner(os.Stdin),
		tokens:  []string{},
		index:   0,
	}
}

func (cs *ConsoleScanner) nextToken() string {
	for cs.index >= len(cs.tokens) {
		if !cs.scanner.Scan() {
			return ""
		}
		cs.tokens = strings.Fields(cs.scanner.Text())
		cs.index = 0
	}
	token := cs.tokens[cs.index]
	cs.index++
	return token
}

func (cs *ConsoleScanner) NextInt() int {
	token := cs.nextToken()
	val, _ := strconv.Atoi(token)
	return val
}

func (cs *ConsoleScanner) NextLong() int64 {
	token := cs.nextToken()
	val, _ := strconv.ParseInt(token, 10, 64)
	return val
}

func (cs *ConsoleScanner) Read() int {
	if !cs.scanner.Scan() {
		return -1
	}
	runes := []rune(cs.scanner.Text())
	if len(runes) == 0 {
		return -1
	}
	return int(runes[0])
}

func (cs *ConsoleScanner) ReadLine() string {
	if !cs.scanner.Scan() {
		return ""
	}
	return cs.scanner.Text()
}

func main() {
	sc := NewConsoleScanner()
	n := sc.NextLong()
	a := sc.NextLong()
	b := sc.NextLong()
	c := sc.NextLong()
	var liters int64 = 0

	if b-c < a && n >= b {
		i := (n-b)/(b-c) + 1
		liters += i
		n -= i * (b - c)
	}
	liters += n / a
	fmt.Println(liters)
}

